INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-boy-wars-2-japan', 'GAMEBOYCOLOR', 'Game Boy Wars 2 (Japan)', '1998', 'Strategy', 'AI', '2', 'Turn-Based Strategy', 'Turn-based tactical military strategy on hexagonal grids.', 'Deploy units and capture enemy bases to win the war.', 'Intense turn-based military strategy.', 'Game Boy Wars 2 offers deep tactical warfare on GBC. Command tanks, infantry, and aircraft in this refined sequel to Nintendo''s classic strategy series.');
