INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('games-frenzy-europe-enfrde', 'GAMEBOYCOLOR', 'Games Frenzy (Europe) (En,Fr,De)', '1999', 'Mini-Games', 'Titus Software', '4', 'Mini-Game Collection', 'Collection of casual mini-games and arcade challenges.', 'Beat high scores and unlock new challenges across various games.', 'Fun variety pack of arcade games.', 'Games Frenzy provides a quick-play experience for GBC. From puzzles to action, this collection offers a bit of everything for gamers on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon---hoshizorashi-dynamites-arawaru!!-japan', 'GAMEBOYCOLOR', 'Ganbare Goemon - Hoshizorashi Dynamites Arawaru!! (Japan)', '2000', 'Action', 'Konami', '1', 'Action-Adventure', 'Side-scrolling action platformer with multiple characters.', 'Stop the cosmic threat and save Japan from new invaders.', 'High-octane Goemon action-platforming.', 'Join Goemon and Ebisumaru in this vibrant GBC adventure. Featuring fast-paced combat and giant robot battles, it''s a must-play for fans of the series.');
