INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon---tengutou-no-gyakushuu-japan', 'GAMEBOYCOLOR', 'Ganbare Goemon - Tengutou no Gyakushuu (Japan)', '2001', 'Action', 'Konami', '1', 'Action-Adventure', 'Turn-based RPG with exploration and cinematic story elements.', 'Defeat the Tengu gang and restore peace to the Edo period.', 'Epic story-driven Goemon RPG.', 'Tengutou no Gyakushuu offers a more narrative-focused experience on GBC. Explore detailed towns and master strategic combat in this classic Goemon quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare!-nippon!-olympic-2000-japan', 'GAMEBOYCOLOR', 'Ganbare! Nippon! Olympic 2000 (Japan)', '2000', 'Sports', 'Konami', '1', 'Multi-Sport', 'Sports mini-game collection featuring official Olympic events.', 'Compete in various athletic trials to win the gold medal.', 'Official 2000 Olympics sports sim.', 'Relive the Sydney 2000 games on your GBC. Master timing and speed in events like swimming, sprinting, and gymnastics in this Konami classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gb-harobots-japan', 'GAMEBOYCOLOR', 'GB Harobots (Japan)', '2000', 'Action', 'Sunrise Interactive', '1', 'Action', 'Tactical RPG featuring customizable mecha robots from Gundam.', 'Build a squad of Harobots and win strategic robot battles.', 'Mecha-collecting strategy RPG.', 'GB Harobots lets you collect and train iconic robots in a tactical RPG setting. Perfect for fans of the Gundam universe looking for portable strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gb-memory-multi-menu-japan-np', 'GAMEBOYCOLOR', 'GB Memory Multi Menu (Japan) (NP)', '1998', 'Utility', 'Nintendo', '1', 'Utility', 'Menu system for the NP (Nintendo Power) flash cartridge system.', 'Navigate and launch multiple games stored on the cart.', 'Official Nintendo flash cart menu.', 'This official tool allowed Japanese GBC owners to manage multiple games downloaded from Nintendo Power kiosks onto a single rewritable cartridge.');
