INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luca-no-puzzle-de-daibouken!-japan', 'GAMEBOYCOLOR', 'Luca no Puzzle de Daibouken! (Japan)', '1999', 'Puzzle', 'Imagineer', '1', 'Adventure Puzzle', 'Tile-matching puzzle adventure featuring characters from DQM2.', 'Solve puzzles to progress through a whimsical fantasy story.', 'Whimsical fantasy puzzle-adventure.', 'Join Luca in this Dragon Quest Monsters 2 spin-off. Luca no Puzzle de Daibouken offers challenging tile puzzles wrapped in a charming RPG-style narrative for GBC.');
