INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marble-madness-usa', 'GAMEBOYCOLOR', 'Marble Madness (USA)', '1999', 'Action / Arcade', 'Digital Eclipse', '1', 'Classic arcade adaptation', 'Isometric physics-based arcade game using a marble.', 'Guide the marble to the goal while avoiding obstacles and falling.', 'Classic physics-based arcade challenge.', 'The arcade legend Marble Madness comes to GBC. Master the tricky isometric paths and race against the clock in this faithful and difficult handheld port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marie-no-atelier-gb-japan', 'GAMEBOYCOLOR', 'Marie no Atelier GB (Japan)', '1999', 'RPG', 'Gust', '1', 'Turn-based RPG', 'Alchemy-based RPG with item crafting and turn-based combat.', 'Manage an alchemy shop and graduate from the academy with honors.', 'Charming alchemy and shop sim RPG.', 'Marie no Atelier GB brings the beloved Atelier series to handheld. Explore, gather materials, and craft unique items in this deep and cozy Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvin-strikes-back!-usa-enfres', 'GAMEBOYCOLOR', 'Marvin Strikes Back! (USA) (En,Fr,Es)', '2000', 'Action / Platform', 'Rare', '1', 'Cartoon platformer', 'Side-scrolling platformer starring Marvin the Martian.', 'Defeat the Looney Tunes and conquer Earth using alien gadgets.', 'Villain-led cartoon platforming.', 'Take control of the Martian in Marvin Strikes Back! Use futuristic weapons and alien technology to stop Bugs Bunny and friends in this fun GBC action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-kate-&-ashley---get-a-clue!-usa-europe', 'GAMEBOYCOLOR', 'Mary-Kate & Ashley - Get a Clue! (USA, Europe)', '2000', 'Adventure', 'Griptonite Games', '1', 'Mystery adventure', 'Mystery-solving adventure with exploration and mini-games.', 'Find clues and solve cases alongside Mary-Kate and Ashley.', 'Olsen twins mystery adventure.', 'Become a detective in Get a Clue! Join the famous twins on GBC to solve neighborhood mysteries through puzzles and exploration in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-kate-and-ashley---crush-course-usa', 'GAMEBOYCOLOR', 'Mary-Kate and Ashley - Crush Course (USA)', '2001', 'Sports / Racing', 'Barking Lizards', '1', 'Obstacle racing', 'Mini-game collection focused on social activities and dating.', 'Complete various social challenges and win over your crush.', 'Social-themed mini-game collection.', 'Join the Olsen twins in Crush Course. This GBC title features a variety of casual games and social simulations designed for fans of the iconic duo.');